style:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&display=swap');

#gj-dash, #gj-dash * {
  box-sizing: border-box;
  font-family: 'DM Sans', -apple-system, sans-serif !important;
}

#gj-dash {
  background: #f1f5f9;
  padding: 4px 4px 32px;
  animation: gj-fadeup 0.4s ease both;
}

/* ── Hero ─────────────────────────────────────── */
#gj-hero {
  background: linear-gradient(135deg, #0a1628 0%, #0f2d5c 40%, #0e4a78 70%, #0a6082 100%);
  border-radius: 20px;
  padding: 26px 30px;
  margin-bottom: 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  position: relative;
  overflow: hidden;
  min-height: 148px;
}

#gj-hero-deco {
  position: absolute;
  right: -30px;
  top: -30px;
  width: 280px;
  height: 280px;
  pointer-events: none;
}

#gj-hero::before {
  content: '';
  position: absolute;
  bottom: -60px;
  left: 25%;
  width: 200px;
  height: 200px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(16,185,129,0.1) 0%, transparent 70%);
  pointer-events: none;
}

#gj-brand {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 16px;
}

#gj-brand-icon {
  width: 54px;
  height: 54px;
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 15px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

#gj-co-title {
  font-size: 19px !important;
  font-weight: 800 !important;
  color: #fff !important;
  letter-spacing: 0.3px;
  line-height: 1.2;
}

#gj-co-sub {
  font-size: 10px !important;
  color: rgba(255,255,255,0.42) !important;
  letter-spacing: 1.8px;
  text-transform: uppercase;
  margin-top: 3px;
}

#gj-hero-left h1 {
  font-size: 20px !important;
  font-weight: 700 !important;
  color: #fff !important;
  letter-spacing: -0.3px;
  margin-bottom: 5px !important;
}

#gj-hero-left p {
  font-size: 12.5px !important;
  color: rgba(255,255,255,0.42) !important;
  margin: 0 !important;
}

#gj-hero-right {
  display: flex;
  gap: 10px;
  align-items: center;
  position: relative;
  z-index: 1;
}

.gj-co-badge {
  background: rgba(255,255,255,0.07);
  border: 1px solid rgba(255,255,255,0.14);
  border-radius: 12px;
  padding: 10px 16px;
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  transition: all 0.2s;
  backdrop-filter: blur(6px);
}

.gj-co-badge:hover {
  background: rgba(255,255,255,0.16);
  transform: translateY(-2px);
}

.gj-co-badge-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex-shrink: 0;
  box-shadow: 0 0 8px currentColor;
}

.gj-co-name {
  font-size: 12.5px !important;
  font-weight: 700 !important;
  color: #fff !important;
}

.gj-co-label {
  font-size: 10px !important;
  color: rgba(255,255,255,0.38) !important;
  margin-top: 2px;
}

#gj-refresh {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.2);
  color: #fff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.25s;
}

#gj-refresh:hover {
  background: rgba(255,255,255,0.22);
  transform: rotate(90deg);
}

/* ── KPI Cards ───────────────────────────────── */
#gj-kpis {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin-bottom: 16px;
}

.gj-kpi {
  background: #ffffff;
  border-radius: 16px;
  padding: 18px 18px 14px;
  box-shadow: 0 1px 12px rgba(15,30,61,0.07);
  border-left: 3px solid var(--kc, #4e8cff);
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s;
}

.gj-kpi:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 28px rgba(15,30,61,0.13);
}

.gj-kpi-icon-wrap {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 12px;
}

.gj-kpi-label {
  font-size: 10px !important;
  font-weight: 700 !important;
  color: #7c8ba1 !important;
  text-transform: uppercase;
  letter-spacing: 0.7px;
  margin-bottom: 8px !important;
}

.gj-kpi-value {
  font-size: 24px !important;
  font-weight: 800 !important;
  color: #1a2340 !important;
  letter-spacing: -0.8px;
  line-height: 1;
  min-height: 28px;
}

.gj-kpi-sub {
  margin-top: 10px;
  font-size: 11.5px !important;
  font-weight: 600 !important;
  min-height: 16px;
}

/* ── Skeleton ────────────────────────────────── */
.gj-skel {
  display: block;
  height: 22px;
  border-radius: 6px;
  background: linear-gradient(90deg, #e8eef8 25%, #f4f7fc 50%, #e8eef8 75%);
  background-size: 200% 100%;
  animation: gj-shimmer 1.4s infinite;
}

@keyframes gj-shimmer {
  0%   { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

@keyframes gj-fadeup {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ── Stat Row ────────────────────────────────── */
#gj-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 18px;
}

.gj-stat {
  background: #ffffff;
  border-radius: 12px;
  padding: 14px 16px;
  display: flex;
  align-items: center;
  gap: 14px;
  box-shadow: 0 1px 8px rgba(15,30,61,0.05);
  border: 1px solid #e8edf5;
  transition: box-shadow 0.2s;
}

.gj-stat:hover {
  box-shadow: 0 4px 16px rgba(15,30,61,0.09);
}

.gj-stat-dot {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.gj-stat-label {
  font-size: 10px !important;
  font-weight: 700 !important;
  color: #7c8ba1 !important;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  margin-bottom: 4px !important;
}

.gj-stat-val {
  font-size: 18px !important;
  font-weight: 800 !important;
  color: #1a2340 !important;
  letter-spacing: -0.3px;
}

/* ── Section Title ───────────────────────────── */
.gj-section-title {
  font-size: 10.5px !important;
  font-weight: 800 !important;
  color: #7c8ba1 !important;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  margin-bottom: 12px !important;
  margin-top: 4px !important;
  display: flex;
  align-items: center;
  gap: 10px;
}

.gj-section-title::after {
  content: '';
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, #dde3ef, transparent);
}

/* ── Quick Actions ───────────────────────────── */
#gj-actions {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 10px;
  margin-bottom: 20px;
}

.gj-action {
  background: #ffffff;
  border-radius: 14px;
  padding: 14px 8px 12px;
  text-align: center;
  cursor: pointer;
  border: 1px solid #e8edf5;
  box-shadow: 0 1px 6px rgba(15,30,61,0.04);
  transition: all 0.18s;
}

.gj-action:hover {
  border-color: #4e8cff;
  box-shadow: 0 4px 18px rgba(78,140,255,0.14);
  transform: translateY(-3px);
}

.gj-action-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  margin: 0 auto 9px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.gj-action-label {
  font-size: 11px !important;
  font-weight: 600 !important;
  color: #334155 !important;
  line-height: 1.3;
}

/* ── Bottom Grid ─────────────────────────────── */
#gj-bottom {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 16px;
}

.gj-card {
  background: #ffffff;
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0 2px 14px rgba(15,30,61,0.06);
  border: 1px solid #e8edf5;
}

.gj-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 14px;
}

.gj-card-title {
  font-size: 14px !important;
  font-weight: 700 !important;
  color: #1a2340 !important;
  display: flex;
  align-items: center;
}

.gj-card-link {
  font-size: 12px !important;
  color: #4e8cff !important;
  font-weight: 600 !important;
  cursor: pointer;
}

.gj-card-link:hover { text-decoration: underline; }

/* ── Invoice Rows ────────────────────────────── */
.gj-inv-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 0;
  border-bottom: 1px solid #f1f5f9;
}

.gj-inv-row:last-child { border-bottom: none; }

.gj-inv-icon {
  width: 34px;
  height: 34px;
  border-radius: 9px;
  background: #eef4ff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  flex-shrink: 0;
}

.gj-inv-info { flex: 1; padding: 0 12px; }

.gj-inv-name {
  font-size: 12.5px !important;
  font-weight: 700 !important;
  color: #4e8cff !important;
  cursor: pointer;
  display: block;
}

.gj-inv-name:hover { text-decoration: underline; }

.gj-inv-party {
  font-size: 11.5px !important;
  color: #7c8ba1 !important;
  margin-top: 2px;
}

.gj-inv-right { text-align: right; flex-shrink: 0; }

.gj-inv-amount {
  font-size: 13px !important;
  font-weight: 800 !important;
  color: #1a2340 !important;
}

/* ── Stock Rows ──────────────────────────────── */
.gj-stock-row {
  padding: 9px 0;
  border-bottom: 1px solid #f1f5f9;
}

.gj-stock-row:last-child { border-bottom: none; }

.gj-stock-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.gj-stock-item {
  font-size: 12px !important;
  font-weight: 600 !important;
  color: #1a2340 !important;
  flex: 1;
  padding-right: 8px;
  line-height: 1.4;
}

.gj-stock-meta {
  font-size: 11px !important;
  color: #7c8ba1 !important;
  margin-top: 3px;
}

.gj-prog-wrap {
  background: #f1f5f9;
  border-radius: 20px;
  height: 4px;
  margin-top: 7px;
  overflow: hidden;
}

.gj-prog-bar {
  height: 4px;
  border-radius: 20px;
  transition: width 1s ease;
}

/* ── Badges ──────────────────────────────────── */
.gj-badge {
  display: inline-block;
  padding: 3px 9px;
  border-radius: 20px;
  font-size: 10px !important;
  font-weight: 700 !important;
  flex-shrink: 0;
}

.badge-green  { background: #dcfce7; color: #16a34a !important; }
.badge-orange { background: #fef3c7; color: #d97706 !important; }
.badge-red    { background: #fee2e2; color: #dc2626 !important; }
.badge-blue   { background: #dbeafe; color: #1d4ed8 !important; }
.badge-purple { background: #ede9fe; color: #7c3aed !important; }
.badge-gray   { background: #f1f5f9; color: #64748b !important; }

/* ── Empty State ─────────────────────────────── */
.gj-empty {
  text-align: center;
  padding: 24px;
  color: #7c8ba1;
  font-size: 13px;
}

.gpf-menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 14px;
  margin-top: 8px;
  font-family: "DM Sans", "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
.gpf-tile {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 20px 12px;
  background: #ffffff;
  border: 1px solid #e0ecff;
  border-radius: 14px;
  box-shadow: 0 8px 24px -12px rgba(30, 64, 175, 0.25);
  text-decoration: none;
  color: #1e293b;
  font-weight: 600;
  font-size: 13px;
  line-height: 1.3;
  text-align: center;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}
.gpf-tile:hover {
  transform: translateY(-4px);
  box-shadow: 0 14px 32px -12px rgba(30, 64, 175, 0.35);
  border-color: #93c5fd;
  color: #1d4ed8;
  text-decoration: none;
}
.gpf-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  font-size: 22px;
  background: linear-gradient(135deg, #eff6ff, #dbeafe);
  transition: background 0.25s ease, transform 0.25s ease;
}
.gpf-tile:hover .gpf-icon {
  background: linear-gradient(135deg, #38bdf8, #2563eb);
  transform: scale(1.08) rotate(-4deg);
}
.gpf-tile.gpf-accent .gpf-icon {
  background: linear-gradient(135deg, #fed7aa, #fb923c);
}
.gpf-tile.gpf-accent:hover .gpf-icon {
  background: linear-gradient(135deg, #fb923c, #ea580c);
}
.gpf-label {
  display: block;
}

