script:
(function () {

  /* ── Config ──────────────────────────────────────────────────── */
  var LOW = 50; // qty threshold for "low stock" alert

  /* ── Helpers ─────────────────────────────────────────────────── */
  function el(id)          { return document.getElementById(id); }
  function setEl(id, html) { var e = el(id); if (e) e.innerHTML  = html; }
  function setTxt(id, txt) { var e = el(id); if (e) e.textContent = txt; }

  /** Format a number as ₹ with Cr / L shorthand */
  function fmtINR(val) {
    val = parseFloat(val) || 0;
    if (val >= 10000000) return '₹' + (val / 10000000).toFixed(2) + ' Cr';
    if (val >= 100000)   return '₹' + (val / 100000).toFixed(2)   + ' L';
    return '₹' + new Intl.NumberFormat('en-IN', { minimumFractionDigits: 0 }).format(val);
  }

  /** Format a number as full ₹ with 2 decimals */
  function fmtFull(val) {
    return '₹' + new Intl.NumberFormat('en-IN', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }).format(parseFloat(val) || 0);
  }

  function today()    { return frappe.datetime.get_today(); }

  function greeting() {
    var h = new Date().getHours();
    return h < 12 ? 'Good Morning' : h < 17 ? 'Good Afternoon' : 'Good Evening';
  }

  function dateStr() {
    return new Date().toLocaleDateString('en-IN', {
      weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
    });
  }

  /** Return a coloured badge <span> for a given status string */
  function badge(status) {
    var map = {
      'Paid':        'badge-green',
      'Unpaid':      'badge-orange',
      'Overdue':     'badge-red',
      'Submitted':   'badge-blue',
      'Draft':       'badge-gray',
      'To Bill':     'badge-purple',
      'Billed':      'badge-green',
      'To Receive':  'badge-orange',
      'Received':    'badge-green',
      'To Pay':      'badge-purple',
      'Cancelled':   'badge-red'
    };
    return '<span class="gj-badge ' + (map[status] || 'badge-gray') + '">' + status + '</span>';
  }

  /** Derive a display status from a Sales Invoice doc */
  function invStatus(doc) {
    if (doc.docstatus === 2)                              return 'Cancelled';
    if (doc.docstatus === 0)                              return 'Draft';
    if ((doc.outstanding_amount || 0) <= 0)              return 'Paid';
    if (doc.due_date && doc.due_date < today())          return 'Overdue';
    return 'Unpaid';
  }

  /* ── Data loaders ────────────────────────────────────────────── */

  function loadHeader() {
    setTxt('gj-greeting', greeting() + ' 👋');
    setTxt('gj-date-str', dateStr() + ' · Gajanand House');
  }

  function loadTodaySales() {
    frappe.db.get_list('Sales Invoice', {
      filters: [['posting_date', '=', today()], ['docstatus', '=', 1]],
      fields: ['name', 'grand_total'],
      limit: 500
    }).then(function (docs) {
      var total = docs.reduce(function (s, d) { return s + (d.grand_total || 0); }, 0);
      setTxt('kpi-today-sales', fmtINR(total));
      setEl('kpi-today-count', '▲ ' + docs.length + ' invoice' + (docs.length !== 1 ? 's' : '') + ' today');
    }).catch(function () { setTxt('kpi-today-sales', '—'); });
  }

  function loadAR() {
    frappe.db.get_list('Sales Invoice', {
      filters: [['docstatus', '=', 1], ['outstanding_amount', '>', 0]],
      fields: ['name', 'outstanding_amount', 'due_date'],
      limit: 500
    }).then(function (docs) {
      var total = docs.reduce(function (s, d) { return s + (d.outstanding_amount || 0); }, 0);
      var od    = docs.filter(function (d) { return d.due_date && d.due_date < today(); }).length;
      setTxt('kpi-ar', fmtINR(total));
      setEl('kpi-ar-sub', od > 0 ? '⚠️ ' + od + ' overdue' : '✅ All on time');
      setTxt('stat-unpaid',  docs.length + ' invoices');
      setTxt('stat-overdue', od          + ' invoices');
    }).catch(function () { setTxt('kpi-ar', '—'); });
  }

  function loadPO() {
    frappe.db.get_list('Purchase Order', {
      filters: [['docstatus', '=', 1], ['per_received', '<', 100]],
      fields: ['name', 'grand_total'],
      limit: 200
    }).then(function (docs) {
      var total = docs.reduce(function (s, d) { return s + (d.grand_total || 0); }, 0);
      setTxt('kpi-po', docs.length + ' orders');
      setEl('kpi-po-sub', 'Value: ' + fmtINR(total));
    }).catch(function () { setTxt('kpi-po', '—'); });
  }

  function loadStock() {
    frappe.call({
      method: 'frappe.client.get_list',
      args: {
        doctype: 'Bin',
        filters: [['actual_qty', '<=', LOW]],
        fields: ['item_code', 'warehouse', 'actual_qty', 'stock_uom'],
        limit: 50,
        order_by: 'actual_qty asc'
      },
      callback: function (r) {
        var docs = (r && r.message) || [];
        var out  = docs.filter(function (d) { return (d.actual_qty || 0) <= 0; }).length;

        setTxt('kpi-stock', (out + (docs.length - out)) + ' items');
        setEl('kpi-stock-sub', out > 0
          ? '🔴 ' + out + ' out of stock'
          : '🟡 ' + (docs.length - out) + ' low stock'
        );

        // PR pending billing count
        frappe.db.get_list('Purchase Receipt', {
          filters: [['docstatus', '=', 1], ['per_billed', '<', 100]],
          fields: ['name'],
          limit: 100
        }).then(function (prs) {
          setTxt('stat-pr-unbilled', (prs.length || 0) + ' receipts');
        }).catch(function () {});

        if (!docs.length) {
          setEl('gj-stock-list', '<div class="gj-empty">✅ No stock alerts</div>');
          return;
        }

        var html = docs.slice(0, 6).map(function (doc) {
          var qty   = parseFloat(doc.actual_qty) || 0;
          var isOut = qty <= 0;
          var pct   = isOut ? 0 : Math.min(100, Math.round((qty / LOW) * 100));
          var color = isOut ? '#ef4444' : '#f59e0b';
          return '<div class="gj-stock-row">'
            + '<div class="gj-stock-top">'
            +   '<div class="gj-stock-item">' + doc.item_code + '</div>'
            +   '<span class="gj-badge ' + (isOut ? 'badge-red' : 'badge-orange') + '">'
            +     (isOut ? 'Out of Stock' : 'Low Stock') + '</span>'
            + '</div>'
            + '<div class="gj-stock-meta">'
            +   qty.toFixed(3) + ' ' + (doc.stock_uom || 'KG') + ' · ' + doc.warehouse
            + '</div>'
            + '<div class="gj-prog-wrap">'
            +   '<div class="gj-prog-bar" style="width:' + pct + '%;background:' + color + '"></div>'
            + '</div>'
            + '</div>';
        }).join('');
        setEl('gj-stock-list', html);
      }
    });
  }

  function loadRecentInvoices() {
    frappe.db.get_list('Sales Invoice', {
      filters: [['docstatus', '=', 1]],
      fields: ['name', 'customer', 'posting_date', 'grand_total', 'outstanding_amount', 'due_date'],
      limit: 6,
      order_by: 'modified desc'
    }).then(function (docs) {
      if (!docs || !docs.length) {
        setEl('gj-sinv-list', '<div class="gj-empty">No invoices found</div>');
        return;
      }
      var html = docs.map(function (doc) {
        var st = invStatus(doc);
        return '<div class="gj-inv-row">'
          + '<div class="gj-inv-icon">🧾</div>'
          + '<div class="gj-inv-info">'
          +   '<span class="gj-inv-name" onclick="frappe.set_route(\'Form/Sales Invoice/' + doc.name + '\')">'
          +     doc.name + '</span>'
          +   '<div class="gj-inv-party">'
          +     doc.customer + ' · ' + frappe.datetime.str_to_user(doc.posting_date)
          +   '</div>'
          + '</div>'
          + '<div class="gj-inv-right">'
          +   '<div class="gj-inv-amount">' + fmtFull(doc.grand_total) + '</div>'
          +   '<div style="margin-top:4px">' + badge(st) + '</div>'
          + '</div>'
          + '</div>';
      }).join('');
      setEl('gj-sinv-list', html);
    }).catch(function () {
      setEl('gj-sinv-list', '<div class="gj-empty">Could not load</div>');
    });
  }

  /* ── Main entry ──────────────────────────────────────────────── */
  function loadAll() {
    loadHeader();
    loadTodaySales();
    loadAR();
    loadPO();
    loadStock();
    loadRecentInvoices();
  }

  // Expose for the refresh button: onclick="gjDashInit()"
  window.gjDashInit = loadAll;

  // Wait for frappe.db to be ready before first load
  function waitForFrappe() {
    if (typeof frappe !== 'undefined' && frappe.db && frappe.datetime) {
      loadAll();
    } else {
      setTimeout(waitForFrappe, 100);
    }
  }

  waitForFrappe();

})();

style:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&display=swap');

/* ── Reset & base ─────────────────────────────── */
#gj-dash, #gj-dash * {
  box-sizing: border-box;
  font-family: 'DM Sans', -apple-system, sans-serif !important;
}

#gj-dash {
  background: #f1f5f9;
  padding: 4px 4px 32px;
  animation: gj-fadeup 0.4s ease both;
}

/* ── Hero ─────────────────────────────────────── */
#gj-hero {
  background: linear-gradient(135deg, #0a1628 0%, #0f2d5c 40%, #0e4a78 70%, #0a6082 100%);
  border-radius: 20px;
  padding: 26px 30px;
  margin-bottom: 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  position: relative;
  overflow: hidden;
  min-height: 148px;
}

/* Large background film-reel illustration */
#gj-hero-deco {
  position: absolute;
  right: -30px;
  top: -30px;
  width: 280px;
  height: 280px;
  pointer-events: none;
}

/* Subtle radial glow bottom-left */
#gj-hero::before {
  content: '';
  position: absolute;
  bottom: -60px;
  left: 25%;
  width: 200px;
  height: 200px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(16,185,129,0.1) 0%, transparent 70%);
  pointer-events: none;
}

/* Brand row (icon + company name + tagline) */
#gj-brand {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 16px;
}

#gj-brand-icon {
  width: 54px;
  height: 54px;
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 15px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

#gj-co-title {
  font-size: 19px !important;
  font-weight: 800 !important;
  color: #fff !important;
  letter-spacing: 0.3px;
  line-height: 1.2;
}

#gj-co-sub {
  font-size: 10px !important;
  color: rgba(255,255,255,0.42) !important;
  letter-spacing: 1.8px;
  text-transform: uppercase;
  margin-top: 3px;
}

#gj-hero-left h1 {
  font-size: 20px !important;
  font-weight: 700 !important;
  color: #fff !important;
  letter-spacing: -0.3px;
  margin-bottom: 5px !important;
}

#gj-hero-left p {
  font-size: 12.5px !important;
  color: rgba(255,255,255,0.42) !important;
  margin: 0 !important;
}

#gj-hero-right {
  display: flex;
  gap: 10px;
  align-items: center;
  position: relative;
  z-index: 1;
}

/* Company status badges */
.gj-co-badge {
  background: rgba(255,255,255,0.07);
  border: 1px solid rgba(255,255,255,0.14);
  border-radius: 12px;
  padding: 10px 16px;
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  transition: all 0.2s;
  backdrop-filter: blur(6px);
}

.gj-co-badge:hover {
  background: rgba(255,255,255,0.16);
  transform: translateY(-2px);
}

.gj-co-badge-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex-shrink: 0;
  box-shadow: 0 0 8px currentColor;
}

.gj-co-name {
  font-size: 12.5px !important;
  font-weight: 700 !important;
  color: #fff !important;
}

.gj-co-label {
  font-size: 10px !important;
  color: rgba(255,255,255,0.38) !important;
  margin-top: 2px;
}

/* Refresh button */
#gj-refresh {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.2);
  color: #fff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.25s;
}

#gj-refresh:hover {
  background: rgba(255,255,255,0.22);
  transform: rotate(90deg);
}

/* ── KPI Cards ───────────────────────────────── */
#gj-kpis {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin-bottom: 16px;
}

.gj-kpi {
  background: #ffffff;
  border-radius: 16px;
  padding: 18px 18px 14px;
  box-shadow: 0 1px 12px rgba(15,30,61,0.07);
  border-left: 3px solid var(--kc, #4e8cff);
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s;
}

.gj-kpi:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 28px rgba(15,30,61,0.13);
}

.gj-kpi-icon-wrap {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 12px;
}

.gj-kpi-label {
  font-size: 10px !important;
  font-weight: 700 !important;
  color: #7c8ba1 !important;
  text-transform: uppercase;
  letter-spacing: 0.7px;
  margin-bottom: 8px !important;
}

.gj-kpi-value {
  font-size: 24px !important;
  font-weight: 800 !important;
  color: #1a2340 !important;
  letter-spacing: -0.8px;
  line-height: 1;
  min-height: 28px;
}

.gj-kpi-sub {
  margin-top: 10px;
  font-size: 11.5px !important;
  font-weight: 600 !important;
  min-height: 16px;
}

/* ── Skeleton loader ─────────────────────────── */
.gj-skel {
  display: block;
  height: 22px;
  border-radius: 6px;
  background: linear-gradient(90deg, #e8eef8 25%, #f4f7fc 50%, #e8eef8 75%);
  background-size: 200% 100%;
  animation: gj-shimmer 1.4s infinite;
}

@keyframes gj-shimmer {
  0%   { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

@keyframes gj-fadeup {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ── Stat Row ────────────────────────────────── */
#gj-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 18px;
}

.gj-stat {
  background: #ffffff;
  border-radius: 12px;
  padding: 14px 16px;
  display: flex;
  align-items: center;
  gap: 14px;
  box-shadow: 0 1px 8px rgba(15,30,61,0.05);
  border: 1px solid #e8edf5;
  transition: box-shadow 0.2s;
}

.gj-stat:hover {
  box-shadow: 0 4px 16px rgba(15,30,61,0.09);
}

.gj-stat-dot {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.gj-stat-label {
  font-size: 10px !important;
  font-weight: 700 !important;
  color: #7c8ba1 !important;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  margin-bottom: 4px !important;
}

.gj-stat-val {
  font-size: 18px !important;
  font-weight: 800 !important;
  color: #1a2340 !important;
  letter-spacing: -0.3px;
}

/* ── Section Title ───────────────────────────── */
.gj-section-title {
  font-size: 10.5px !important;
  font-weight: 800 !important;
  color: #7c8ba1 !important;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  margin-bottom: 12px !important;
  margin-top: 4px !important;
  display: flex;
  align-items: center;
  gap: 10px;
}

.gj-section-title::after {
  content: '';
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, #dde3ef, transparent);
}

/* ── Quick Actions ───────────────────────────── */
#gj-actions {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 10px;
  margin-bottom: 20px;
}

.gj-action {
  background: #ffffff;
  border-radius: 14px;
  padding: 14px 8px 12px;
  text-align: center;
  cursor: pointer;
  border: 1px solid #e8edf5;
  box-shadow: 0 1px 6px rgba(15,30,61,0.04);
  transition: all 0.18s;
}

.gj-action:hover {
  border-color: #4e8cff;
  box-shadow: 0 4px 18px rgba(78,140,255,0.14);
  transform: translateY(-3px);
}

.gj-action-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  margin: 0 auto 9px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.gj-action-label {
  font-size: 11px !important;
  font-weight: 600 !important;
  color: #334155 !important;
  line-height: 1.3;
}

/* ── Bottom Grid ─────────────────────────────── */
#gj-bottom {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 16px;
}

.gj-card {
  background: #ffffff;
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0 2px 14px rgba(15,30,61,0.06);
  border: 1px solid #e8edf5;
}

.gj-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 14px;
}

.gj-card-title {
  font-size: 14px !important;
  font-weight: 700 !important;
  color: #1a2340 !important;
  display: flex;
  align-items: center;
}

.gj-card-link {
  font-size: 12px !important;
  color: #4e8cff !important;
  font-weight: 600 !important;
  cursor: pointer;
}

.gj-card-link:hover { text-decoration: underline; }

/* ── Invoice Rows ────────────────────────────── */
.gj-inv-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 0;
  border-bottom: 1px solid #f1f5f9;
}

.gj-inv-row:last-child { border-bottom: none; }

.gj-inv-icon {
  width: 34px;
  height: 34px;
  border-radius: 9px;
  background: #eef4ff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  flex-shrink: 0;
}

.gj-inv-info { flex: 1; padding: 0 12px; }

.gj-inv-name {
  font-size: 12.5px !important;
  font-weight: 700 !important;
  color: #4e8cff !important;
  cursor: pointer;
  display: block;
}

.gj-inv-name:hover { text-decoration: underline; }

.gj-inv-party {
  font-size: 11.5px !important;
  color: #7c8ba1 !important;
  margin-top: 2px;
}

.gj-inv-right { text-align: right; flex-shrink: 0; }

.gj-inv-amount {
  font-size: 13px !important;
  font-weight: 800 !important;
  color: #1a2340 !important;
}

/* ── Stock Rows ──────────────────────────────── */
.gj-stock-row {
  padding: 9px 0;
  border-bottom: 1px solid #f1f5f9;
}

.gj-stock-row:last-child { border-bottom: none; }

.gj-stock-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.gj-stock-item {
  font-size: 12px !important;
  font-weight: 600 !important;
  color: #1a2340 !important;
  flex: 1;
  padding-right: 8px;
  line-height: 1.4;
}

.gj-stock-meta {
  font-size: 11px !important;
  color: #7c8ba1 !important;
  margin-top: 3px;
}

.gj-prog-wrap {
  background: #f1f5f9;
  border-radius: 20px;
  height: 4px;
  margin-top: 7px;
  overflow: hidden;
}

.gj-prog-bar {
  height: 4px;
  border-radius: 20px;
  transition: width 1s ease;
}

/* ── Status Badges ───────────────────────────── */
.gj-badge {
  display: inline-block;
  padding: 3px 9px;
  border-radius: 20px;
  font-size: 10px !important;
  font-weight: 700 !important;
  flex-shrink: 0;
}

.badge-green  { background: #dcfce7; color: #16a34a !important; }
.badge-orange { background: #fef3c7; color: #d97706 !important; }
.badge-red    { background: #fee2e2; color: #dc2626 !important; }
.badge-blue   { background: #dbeafe; color: #1d4ed8 !important; }
.badge-purple { background: #ede9fe; color: #7c3aed !important; }
.badge-gray   { background: #f1f5f9; color: #64748b !important; }

/* ── Empty State ─────────────────────────────── */
.gj-empty {
  text-align: center;
  padding: 24px;
  color: #7c8ba1;
  font-size: 13px;
}

.gpf-menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 14px;
  margin-top: 8px;
  font-family: "DM Sans", "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
.gpf-tile {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 20px 12px;
  background: #ffffff;
  border: 1px solid #e0ecff;
  border-radius: 14px;
  box-shadow: 0 8px 24px -12px rgba(30, 64, 175, 0.25);
  text-decoration: none;
  color: #1e293b;
  font-weight: 600;
  font-size: 13px;
  line-height: 1.3;
  text-align: center;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}
.gpf-tile:hover {
  transform: translateY(-4px);
  box-shadow: 0 14px 32px -12px rgba(30, 64, 175, 0.35);
  border-color: #93c5fd;
  color: #1d4ed8;
  text-decoration: none;
}
.gpf-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  font-size: 22px;
  background: linear-gradient(135deg, #eff6ff, #dbeafe);
  transition: background 0.25s ease, transform 0.25s ease;
}
.gpf-tile:hover .gpf-icon {
  background: linear-gradient(135deg, #38bdf8, #2563eb);
  transform: scale(1.08) rotate(-4deg);
}
.gpf-tile.gpf-accent .gpf-icon {
  background: linear-gradient(135deg, #fed7aa, #fb923c);
}
.gpf-tile.gpf-accent:hover .gpf-icon {
  background: linear-gradient(135deg, #fb923c, #ea580c);
}
.gpf-label {
  display: block;
}
